/* =========================================================
   FEUGEE SIDEQUEST  -  COLUMN LAYOUT
   SideQuest only.

   panel.css and js/modes.js are shared byte-for-byte by every Feugee plugin,
   so nothing here touches them. Every selector sits behind .cols / .col.

   Why it exists: the shared card grid aligns rows, so a short card reserves a
   whole row and leaves a hole next to a tall one. These are plain columns -
   js/layout.js drops each card into the shortest one, so nothing is left
   hanging and the cards stay in reading order.
   ========================================================= */

/* [hidden] still outranks this, see panel.css */
.content.cols {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  justify-content: center;   /* columns stay centred once they stop growing */
  gap: var(--gap);
}

/* A column stops growing at MAX. Without the cap a wide dock stretched each
   card until the tiles were mostly empty space with a 9px label adrift in the
   middle - the panel looked unfinished rather than roomy. Past the cap the
   extra width becomes even margin on both sides instead. */
.col {
  flex: 1 1 0;
  min-width: 0;
  max-width: 420px;
  display: flex;
  flex-direction: column;
  gap: var(--gap);
}

/* panel.css sets `.card { align-self: start }`. Under the shared GRID that is
   right: it stops a short card from being stretched to the height of the tall
   one beside it. In a flex COLUMN the cross axis is horizontal instead, so the
   same line stops the card being stretched to the WIDTH of its column - every
   card shrank to the width of its own content, which is why the four cards
   measured 246 / 292 / 193 / 228px inside 420px columns and the full view
   looked ragged with gaps that no amount of column arithmetic could close.
   Restore the stretch here rather than editing the shared file. */
.content.cols .card {
  align-self: stretch;
}

files.css/panel.css:
/* =========================================================
   FEUGEE STUDIO - SHARED PANEL STYLES
   Palette derived from the Feugee logo: #F2631C / #60B4E2 / #191919
   Copy this file as-is into every Feugee plugin. Do not fork it per plugin.
   ========================================================= */

/* ---------------------------------------------------------
   8-BIT RETRO PIXEL FONT (Silkscreen)
   Self-contained base64 WOFF2 for zero-latency offline rendering.
   --------------------------------------------------------- */
@font-face {
  font-family: 'Silkscreen';
  font-style: normal;
  font-weight: 400;
  src: url('data:font/woff2;base64,') format('woff2');
}

:root {
  --orange:     #f2631c;
  --orange-dim: rgba(242, 99, 28, 0.16);
  --orange-mid: rgba(242, 99, 28, 0.38);
  --blue:       #60b4e2;
  --blue-dim:   rgba(96, 180, 226, 0.16);
  --blue-mid:   rgba(96, 180, 226, 0.38);
  --danger:     #e05a49;
  --danger-dim: rgba(224, 90, 73, 0.16);
  --danger-mid: rgba(224, 90, 73, 0.38);

  --bg:         #161619;
  --card:       #1e1e22;
  --tile:       #26262c;
  --tile-hover: #33333b;
  --field:      #121215;
  --stroke:     #34343d;
  --stroke-soft:#2a2a31;

  --text:       #f1f1f4;
  --text-dim:   #b9b9c4;
  --text-muted: #7b7b88;

  --radius:     6px;
  --gap:        8px;
}

* { box-sizing: border-box; }

/* must outrank .content / .compact display:grid, otherwise hiding a view fails */
[hidden] { display: none !important; }

html, body {
  height: 100%;
  margin: 0;
  overflow: hidden;
}

body {
  display: flex;
  flex-direction: column;
  background: var(--bg);
  color: var(--text);
  font: 12px/1.45 -apple-system, "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  user-select: none;
  cursor: default;
}

/* ---------------------------------------------------------
   HEADER
   --------------------------------------------------------- */
.topbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px 8px;
  border-bottom: 1px solid var(--stroke-soft);
  background: linear-gradient(180deg, #1b1b1f 0%, var(--bg) 100%);
}

.brand-logo {
  color: #f2f2f5;
  flex: 0 0 auto;
  cursor: pointer;
  transform-origin: center center;
  animation: feugeeLogoFloat 3.8s ease-in-out infinite;
  transition: filter 0.25s ease, transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.brand-logo:hover {
  animation: none;
  transform: translateY(-1px) scale(1.1) rotate(-3deg);
  filter: drop-shadow(0 2px 10px rgba(242, 99, 28, 0.45));
}

.brand-logo:active {
  transform: scale(0.92) rotate(2deg);
}

.brand-logo.logo-pop {
  animation: feugeeLogoClickPop 0.55s cubic-bezier(0.34, 1.56, 0.64, 1) !important;
}

/* Subtle periodic micro-accent on the orange & blue logo shapes */
.brand-logo .fg-l2 {
  transform-origin: 125px 145px;
  animation: feugeeOrangeIdle 5.5s cubic-bezier(0.34, 1.56, 0.64, 1) infinite;
  transition: transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.brand-logo .fg-l4 {
  transform-origin: 165px 135px;
  animation: feugeeBlueIdle 5.5s cubic-bezier(0.34, 1.56, 0.64, 1) infinite;
  transition: transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.brand-logo:hover .fg-l2 {
  animation: none;
  transform: scale(1.18) rotate(6deg);
}

.brand-logo:hover .fg-l4 {
  animation: none;
  transform: scale(1.18) rotate(-6deg);
}

@keyframes feugeeLogoFloat {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-1.8px);
  }
}

@keyframes feugeeOrangeIdle {
  0%, 75%, 100% {
    transform: translateY(0) scale(1) rotate(0deg);
  }
  80% {
    transform: translateY(-2px) scale(1.12) rotate(4deg);
  }
  86% {
    transform: translateY(0.5px) scale(0.98) rotate(-1deg);
  }
  92% {
    transform: translateY(0) scale(1) rotate(0deg);
  }
}

@keyframes feugeeBlueIdle {
  0%, 78%, 100% {
    transform: translateY(0) scale(1) rotate(0deg);
  }
  83% {
    transform: translateY(1.8px) scale(1.12) rotate(-4deg);
  }
  89% {
    transform: translateY(-0.5px) scale(0.98) rotate(1deg);
  }
  95% {
    transform: translateY(0) scale(1) rotate(0deg);
  }
}

@keyframes feugeeLogoClickPop {
  0%   { transform: scale(0.9) rotate(-6deg); }
  45%  { transform: scale(1.22) rotate(4deg); }
  75%  { transform: scale(0.96) rotate(-2deg); }
  100% { transform: scale(1) rotate(0deg); }
}


.brand-text { min-width: 0; }

.brand-text h1 {
  margin: 0;
  font-size: 12.5px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: var(--orange);
  white-space: nowrap;
}

.brand-text p {
  margin: 1px 0 0;
  font-size: 10px;
  color: var(--blue);
  white-space: nowrap;
}

.brand-text p b {
  font-weight: 600;
  opacity: 0.75;
}

/* ---------------------------------------------------------
   DECORATIVE 8-BIT PIXEL MARQUEE TICKER
   --------------------------------------------------------- */
.feugee-ticker {
  flex: 0 0 auto;
  position: relative;
  overflow: hidden;
  height: 22px;
  display: flex;
  align-items: center;
  background-color: #0c0c0f;
  background-image:
    radial-gradient(circle at 1.5px 1.5px, rgba(242, 99, 28, 0.18) 1px, transparent 0),
    repeating-linear-gradient(to bottom, rgba(0, 0, 0, 0.35) 0px, rgba(0, 0, 0, 0.35) 1px, transparent 1px, transparent 2px);
  background-size: 4px 4px, 100% 2px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  border-bottom: 1px solid #000000;
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.7), 0 1px 0 rgba(255, 255, 255, 0.02);
  user-select: none;
  cursor: pointer;
  z-index: 5;
}

.feugee-ticker::before,
.feugee-ticker::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  width: 24px;
  pointer-events: none;
  z-index: 2;
}

.feugee-ticker::before {
  left: 0;
  background: linear-gradient(90deg, #0c0c0f 0%, transparent 100%);
}

.feugee-ticker::after {
  right: 0;
  background: linear-gradient(270deg, #0c0c0f 0%, transparent 100%);
}

.feugee-ticker-track {
  display: flex;
  width: max-content;
  will-change: transform;
  animation: feugeePixelMarquee 50s steps(720, end) infinite;
}

.feugee-ticker:hover .feugee-ticker-track {
  animation-play-state: paused;
}

.feugee-ticker-segment {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  white-space: nowrap;
}

.ticker-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 14px;
}

.pixel-text {
  font-family: 'Silkscreen', 'Courier New', Monaco, 'SF Mono', monospace;
  font-size: 9.5px;
  font-weight: 400;
  line-height: 1;
  letter-spacing: 1.8px;
  color: #ff853a;
  text-transform: uppercase;
  text-shadow:
    0 0 1px #f2631c,
    0 0 4px rgba(242, 99, 28, 0.7),
    0 0 8px rgba(242, 99, 28, 0.35);
  -webkit-font-smoothing: none;
  font-smooth: never;
  image-rendering: pixelated;
  animation: pixelFlicker 7s infinite;
}

.pixel-icon {
  display: inline-block;
  font-size: 10px;
  line-height: 1;
  image-rendering: pixelated;
  animation: pixelBob 0.6s steps(2) infinite;
}

.pixel-icon.icon-spark {
  color: #ffae42;
  text-shadow: 0 0 4px rgba(255, 174, 66, 0.8);
}

.pixel-icon.icon-ghost {
  font-size: 11px;
  animation: pixelBob 0.8s steps(2) infinite reverse;
}

.pixel-icon.icon-star {
  color: #60b4e2;
  text-shadow: 0 0 4px rgba(96, 180, 226, 0.8);
  animation: pixelBob 0.5s steps(2) infinite;
}

.pixel-icon.icon-bolt {
  color: #ffd244;
  text-shadow: 0 0 4px rgba(255, 210, 68, 0.8);
}

.pixel-icon.icon-heart {
  color: #ff4760;
  text-shadow: 0 0 4px rgba(255, 71, 96, 0.8);
  animation: pixelBob 0.7s steps(2) infinite;
}

.pixel-dot {
  font-size: 5px;
  color: rgba(242, 99, 28, 0.5);
  margin: 0 2px;
}

@keyframes feugeePixelMarquee {
  0% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(-50%);
  }
}

@keyframes pixelBob {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-2px);
  }
}

@keyframes pixelFlicker {
  0%, 93%, 100% {
    opacity: 1;
    filter: brightness(1);
  }
  94% {
    opacity: 0.88;
    filter: brightness(1.25) contrast(1.1);
  }
  95% {
    opacity: 1;
    filter: brightness(1);
  }
}

.feugee-ticker.pixel-pop {
  animation: feugeeTickerPop 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

@keyframes feugeeTickerPop {
  0%   { transform: scaleY(0.92); filter: brightness(1.4); }
  50%  { transform: scaleY(1.08); filter: brightness(1.8) hue-rotate(-15deg); }
  100% { transform: scaleY(1); filter: brightness(1); }
}

/* ---------------------------------------------------------
   SCROLL AREA  -  this is what makes wheel scrolling work
   Card grid: column count follows panel width smoothly instead of
   jumping between fixed breakpoints.
   --------------------------------------------------------- */
.content {
  flex: 1 1 auto;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
  padding: var(--gap);
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(252px, 100%), 1fr));
  gap: var(--gap);
  align-content: start;
}

.content::-webkit-scrollbar { width: 10px; }
.content::-webkit-scrollbar-track { background: transparent; }
.content::-webkit-scrollbar-thumb {
  background: #3a3a44;
  border-radius: 5px;
  border: 2px solid var(--bg);
}
.content::-webkit-scrollbar-thumb:hover { background: #4a4a57; }

/* ---------------------------------------------------------
   CARD
   --------------------------------------------------------- */
.card {
  background: var(--card);
  border: 1px solid var(--stroke-soft);
  border-radius: var(--radius);
  padding: 9px 10px 11px;
  align-self: start;
}

[data-accent="orange"] { --accent: var(--orange); --accent-dim: var(--orange-dim); --accent-mid: var(--orange-mid); }
[data-accent="blue"]   { --accent: var(--blue);   --accent-dim: var(--blue-dim);   --accent-mid: var(--blue-mid); }

.card-head {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 3px;
}

.card-head .bar {
  width: 3px;
  height: 13px;
  border-radius: 2px;
  background: var(--accent);
  flex: 0 0 auto;
}

.card-head .num {
  font-size: 9.5px;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}

.card-head h2 {
  margin: 0;
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.7px;
  color: var(--accent);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.meta {
  margin: 0 0 8px;
  font-size: 9.5px;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ---------------------------------------------------------
   PARAM FIELDS
   --------------------------------------------------------- */
.params {
  display: flex;
  flex-wrap: wrap;
  gap: 5px 12px;
  margin-bottom: 8px;
}

.field {
  display: flex;
  align-items: center;
  gap: 6px;
}

.field label {
  font-size: 9.5px;
  color: var(--text-muted);
  white-space: nowrap;
}

.field input {
  width: 46px;
  padding: 3px 6px;
  background: var(--field);
  border: 1px solid var(--stroke);
  border-radius: 4px;
  color: var(--text);
  font-weight: 600;
  font-size: 11px;
  line-height: 1.2;
  font-family: inherit;   /* shorthand cannot take `inherit` as the family */
  text-align: center;
  outline: none;
  transition: border-color 0.14s ease, box-shadow 0.14s ease;
}

.field input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent-dim);
}

/* ---------------------------------------------------------
   TILE GRIDS
   --------------------------------------------------------- */
.tiles      { display: grid; gap: 5px; grid-template-columns: repeat(2, 1fr); }
.tiles.solo { grid-template-columns: 1fr; }
.tiles.trio { grid-template-columns: repeat(3, 1fr); }
.tiles + .tiles { margin-top: 5px; }

.tile {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-height: 46px;
  padding: 7px 6px 9px;
  background: var(--tile);
  border: 1px solid var(--stroke);
  border-radius: 5px;
  color: var(--text-dim);
  font-weight: 700;
  font-size: 9px;
  line-height: 1.1;
  font-family: inherit;   /* shorthand cannot take `inherit` as the family */
  letter-spacing: 0.55px;
  text-align: center;
  overflow: hidden;
  cursor: pointer;
  transition: background 0.13s ease, border-color 0.13s ease,
              color 0.13s ease, transform 0.08s ease;
}

.tile svg { width: 20px; height: 20px; flex: 0 0 auto; }
.tile span {
  max-width: 100%;
  /* labels may wrap to a second line rather than being cut with "..." */
  white-space: normal;
  overflow-wrap: break-word;
  line-height: 1.15;
}

/* row variant: icon on the left, label on the right */
.tile.row {
  flex-direction: row;
  gap: 7px;
  min-height: 34px;
  padding: 6px 9px;
}
.tile.row svg { width: 15px; height: 15px; }
.tile.row span, .tile.chip span {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tile.chip {
  min-height: 26px;
  padding: 4px 7px;
  font-size: 8.5px;
  background: #202026;
  border-radius: 4px;
}
.tile.chip svg { width: 13px; height: 13px; }

.tile.danger { --accent: var(--danger); --accent-dim: var(--danger-dim); --accent-mid: var(--danger-mid); }

/* accent underline that grows on hover */
.tile::after {
  content: "";
  position: absolute;
  left: 9px;
  right: 9px;
  bottom: 3px;
  height: 2px;
  border-radius: 1px;
  background: var(--accent);
  transform: scaleX(0);
  transition: transform 0.17s cubic-bezier(0.22, 0.9, 0.3, 1);
}
.tile.chip::after { display: none; }

.tile:hover {
  background: var(--tile-hover);
  border-color: var(--accent);
  color: var(--text);
}
.tile:hover::after { transform: scaleX(1); }
.tile:hover svg { color: var(--accent); }

.tile:active { transform: translateY(1px) scale(0.985); }

/* pulse on click */
@keyframes fgPulse {
  0%   { box-shadow: 0 0 0 0 var(--accent-mid); background: var(--accent-dim); border-color: var(--accent); }
  70%  { box-shadow: 0 0 0 8px rgba(0, 0, 0, 0); }
  100% { box-shadow: 0 0 0 0 rgba(0, 0, 0, 0); }
}
.tile.pulse { animation: fgPulse 0.45s cubic-bezier(0.2, 0.8, 0.3, 1); }

.tile.busy { opacity: 0.55; pointer-events: none; }

.tiles.right { grid-template-columns: 1fr auto; }
.tiles.right .spacer { display: block; }

/* ---------------------------------------------------------
   CHECKBOX
   --------------------------------------------------------- */
.check {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 8px;
  font-size: 9.5px;
  color: var(--text-dim);
  cursor: pointer;
}

.check input { position: absolute; opacity: 0; pointer-events: none; }

.check .box {
  width: 13px;
  height: 13px;
  flex: 0 0 auto;
  border: 1px solid var(--stroke);
  border-radius: 3px;
  background: var(--field);
  position: relative;
  transition: background 0.13s ease, border-color 0.13s ease;
}

.check .box::after {
  content: "";
  position: absolute;
  left: 3.5px;
  top: 0.5px;
  width: 4px;
  height: 8px;
  border: solid #fff;
  border-width: 0 2px 2px 0;
  transform: rotate(45deg) scale(0);
  transition: transform 0.14s cubic-bezier(0.2, 0.9, 0.3, 1.4);
}

.check input:checked + .box { background: var(--blue); border-color: var(--blue); }
.check input:checked + .box::after { transform: rotate(45deg) scale(1); }

/* ---------------------------------------------------------
   FOOTER
   --------------------------------------------------------- */
.statusbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  border-top: 1px solid var(--stroke-soft);
  background: #1a1a1e;
  font-size: 9.5px;
  color: var(--text-dim);
}

.led {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex: 0 0 auto;
  background: var(--text-muted);
  transition: background 0.2s ease, box-shadow 0.2s ease;
}
.led.ok   { background: var(--orange); box-shadow: 0 0 6px var(--orange-mid); }
.led.err  { background: var(--danger); box-shadow: 0 0 6px var(--danger-mid); }

#status {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@keyframes fgFlashText {
  0%   { color: var(--flash, var(--orange)); }
  100% { color: var(--text-dim); }
}
#status.flash { animation: fgFlashText 0.85s ease-out; }

#status.is-err { color: var(--danger); }

/* ---------------------------------------------------------
   SHARED COMPONENTS
   Required in every plugin - never fork these per plugin.
   --------------------------------------------------------- */

/* .sub - small caption separating sub-groups inside one card.
   Use when a card holds two tile groups with different roles. */
.sub {
  margin: 7px 0 4px;
  font-size: 8.5px;
  font-weight: 700;
  letter-spacing: 0.55px;
  text-transform: uppercase;
  color: var(--text-muted);
}
.sub:first-of-type { margin-top: 0; }

/* .tile.is-on - a tile acting as a MODE SWITCH rather than a one-shot action.
   It differs from :hover in exactly one way: the state persists. The visual
   language is deliberately identical to hover so there is no new vocabulary. */
.tile.is-on {
  background: var(--accent-dim);
  border-color: var(--accent);
  color: var(--text);
}
.tile.is-on svg { color: var(--accent); }
.tile.is-on::after { transform: scaleX(1); }
.tile.chip.is-on { background: var(--accent-dim); }

/* an already-on mode tile should not "press" again when re-clicked */
.tile.is-on:active { transform: none; }

/* ---------------------------------------------------------
   VIEW MODES  -  full (cards) <-> compact (buttons only)
   Driven by js/modes.js, which builds the compact view from
   the full markup. No second markup tree to keep in sync.
   --------------------------------------------------------- */

/* segmented switch in the header */
.modes {
  display: flex;
  gap: 2px;
  margin-left: auto;
  flex: 0 0 auto;
  padding: 2px;
  background: var(--field);
  border: 1px solid var(--stroke);
  border-radius: 5px;
}

.modes button {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 20px;
  padding: 0;
  border: 0;
  border-radius: 3px;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition: background 0.13s ease, color 0.13s ease;
}

.modes button svg { width: 13px; height: 13px; }
.modes button:hover { color: var(--text-dim); }

.modes button.on {
  background: var(--tile-hover);
  color: var(--orange);
}

/* reload & update buttons in topbar */
.topbar-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  margin-left: 4px;
  flex: 0 0 auto;
  background: var(--field);
  border: 1px solid var(--stroke);
  border-radius: 5px;
  color: var(--text-muted);
  cursor: pointer;
  transition: background 0.13s ease, border-color 0.13s ease, color 0.13s ease, transform 0.1s ease;
}

.topbar-btn svg {
  width: 13px;
  height: 13px;
  transition: transform 0.3s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.topbar-btn:hover {
  background: var(--tile-hover);
  border-color: var(--orange);
  color: var(--orange);
}

#btnReload:hover svg {
  transform: rotate(90deg);
}

#btnUpdate:hover svg {
  transform: translateY(1.5px);
}

.topbar-btn:active {
  transform: translateY(1px) scale(0.95);
}

.topbar-btn.is-spinning svg,
.topbar-btn.is-updating svg {
  animation: topbarSpin 0.75s linear infinite !important;
}

@keyframes topbarSpin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

/* orange dot notification badge when update is available */
.topbar-btn.has-update {
  border-color: var(--orange-dim);
  color: var(--text);
}

.topbar-btn.has-update::after {
  content: "";
  position: absolute;
  top: 2px;
  right: 2px;
  width: 6px;
  height: 6px;
  background: var(--orange);
  border: 1.5px solid var(--bg);
  border-radius: 50%;
  box-shadow: 0 0 5px var(--orange);
  animation: updatePulse 2s ease-in-out infinite;
  pointer-events: none;
}

@keyframes updatePulse {
  0%, 100% {
    transform: scale(1);
    opacity: 1;
    box-shadow: 0 0 4px var(--orange);
  }
  50% {
    transform: scale(1.3);
    opacity: 0.85;
    box-shadow: 0 0 8px var(--orange);
  }
}

/* compact container - same scroll behaviour as .content */
.compact {
  flex: 1 1 auto;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
  padding: var(--gap);
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(188px, 100%), 1fr));
  gap: 5px;
  align-content: start;
}

.compact::-webkit-scrollbar { width: 10px; }
.compact::-webkit-scrollbar-track { background: transparent; }
.compact::-webkit-scrollbar-thumb {
  background: #3a3a44;
  border-radius: 5px;
  border: 2px solid var(--bg);
}
.compact::-webkit-scrollbar-thumb:hover { background: #4a4a57; }

/* A compact tile is a .tile.row, so it inherits every hover / pulse /
   active / danger rule already defined above. .ctile only adds the
   inline property chips. */
.ctile {
  min-height: 30px;
  padding: 4px 6px 4px 8px;
  gap: 6px;
  justify-content: flex-start;
}

.ctile span {
  flex: 1 1 auto;
  text-align: left;
  min-width: 0;
}

.ctile::after { display: none; }

/* inline editable properties, right-aligned inside the button */
.cvals {
  display: flex;
  flex: 0 0 auto;
  gap: 3px;
  align-items: center;
}

.cval {
  width: 27px;
  padding: 2px 3px;
  background: var(--field);
  border: 1px solid var(--stroke);
  border-radius: 3px;
  color: var(--text);
  font-weight: 700;
  font-size: 9px;
  line-height: 1.2;
  font-family: inherit;   /* shorthand cannot take `inherit` as the family */
  text-align: center;
  outline: none;
  cursor: text;
  transition: border-color 0.13s ease, box-shadow 0.13s ease;
}

.cval:hover  { border-color: var(--accent); }
.cval:focus  { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-dim); }

/* checkbox rendered as a tiny square toggle on the button */
.cchk {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 15px;
  height: 15px;
  flex: 0 0 auto;
  border: 1px solid var(--stroke);
  border-radius: 3px;
  background: var(--field);
  color: transparent;
  transition: background 0.13s ease, border-color 0.13s ease, color 0.13s ease;
}

.cchk svg { width: 9px; height: 9px; }

.cchk.on {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

/* card-name prefix, added only to compact labels that would otherwise collide */
.cgrp {
  font-weight: 700;
  font-size: 8px;
  letter-spacing: 0.5px;
  color: var(--text-muted);
  margin-right: 5px;
}

